        listOf("", "1e332442367e1bd079bafc69b66489f0"),
        listOf("", "a4df91dc0bdcd00c1e05ea0fa443a030"),
    )

    private fun bytes(hex: String) = ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    private fun ints(hex: String) = IntArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16) }

    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }

    private fun hex(b: IntArray) = b.joinToString("") { "%02x".format(it) }

    @Test
    fun setupMatchesC() {
        assertEquals(4, SETUP.size)
        for ((request, reply) in SETUP) assertEquals(reply, hex(FairPlay.setupReply(bytes(request))!!))
    }

    @Test
    fun setupRejectsBadRequests() {
        val good = bytes(SETUP[0][0])
        assertNull(FairPlay.setupReply(good.copyOf(15)))
        assertNull(FairPlay.setupReply(good.copyOf().also { it[4] = 2 }))
        assertNull(FairPlay.setupReply(good.copyOf().also { it[14] = 4 }))
    }

    @Test
    fun handshakeMatchesC() {
        for ((request, reply) in HANDSHAKE) assertEquals(reply, hex(FairPlay.handshakeReply(bytes(request))!!))
        val good = bytes(HANDSHAKE[0][0])
        assertNull(FairPlay.handshakeReply(good.copyOf().also { it[4] = 1 }))
        assertNull(FairPlay.handshakeReply(good.copyOf(163)))
    }

    @Test
    fun decryptKeyMatchesC() {
        assertEquals(32, DECRYPT.size)
        for ((message, ekey, key) in DECRYPT) assertEquals(key, hex(FairPlay.decryptKey(bytes(message), bytes(ekey))))
    }

    @Test
    fun decryptKeyChecksInput() {
        val (message, ekey) = DECRYPT[0]
        assertFailsWith<IllegalArgumentException> { FairPlay.decryptKey(bytes(message).copyOf(163), bytes(ekey)) }
        assertFailsWith<IllegalArgumentException> { FairPlay.decryptKey(bytes(message), bytes(ekey).copyOf(71)) }
        assertFailsWith<IllegalArgumentException> {
            FairPlay.decryptKey(bytes(message).also { it[12] = 4 }, bytes(ekey))
        }
    }

    @Test
    fun decryptKeyLeavesInputsIntact() {
        val (message, ekey, key) = DECRYPT[1]
        val m = bytes(message)
        val e = bytes(ekey)
        assertContentEquals(bytes(key), FairPlay.decryptKey(m, e))
        assertEquals(message, hex(m))
        assertEquals(ekey, hex(e))
    }

    @Test
    fun modifiedMd5MatchesC() {
        for ((block, key, out) in MD5) assertEquals(out, hex(FairPlay.modifiedMd5(ints(block), ints(key))))
    }

    @Test
    fun sapHashMatchesC() {
        for ((block, out) in SAP_HASH) assertEquals(out, hex(FairPlay.sapHash(ints(block))))
    }

    @Test
    fun sessionKeyMatchesC() {
        for ((message, out) in SESSION_KEY) {
            assertEquals(out, hex(FairPlay.generateSessionKey(FairPlay.defaultSap, ints(message))))
        }
    }
}
